export function criarEstoque() {
  return { produtos: [], proximoId: 1 };
}

function validarProduto(produto) {
  if (!produto || typeof produto.nome !== 'string' || produto.nome.trim() === '') {
    throw new Error('nome precisa ser texto não vazio');
  }
  if (typeof produto.preco !== 'number' || produto.preco <= 0) {
    throw new Error('preco precisa ser um número maior que 0');
  }
  if (typeof produto.quantidade !== 'number' || produto.quantidade < 0) {
    throw new Error('quantidade não pode ser negativa');
  }
}

function validarEstoque(estoque) {
  if (!estoque || !Array.isArray(estoque.produtos) || typeof estoque.proximoId !== 'number') {
    throw new Error('estoque inválido');
  }
}

export function adicionarProduto(estoque, produto) {
  validarEstoque(estoque);
  validarProduto(produto);
  const novo = { ...produto, id: estoque.proximoId };
  estoque.produtos.push(novo);
  estoque.proximoId += 1;
  return novo;
}

export function buscarProduto(estoque, id) {
  validarEstoque(estoque);
  return estoque.produtos.find((produto) => produto.id === id);
}

export function atualizarProduto(estoque, id, mudancas) {
  validarEstoque(estoque);
  const produto = estoque.produtos.find((p) => p.id === id);
  if (!produto) return undefined;
  if (mudancas.nome !== undefined) {
    if (typeof mudancas.nome !== 'string' || mudancas.nome.trim() === '') {
      throw new Error('nome precisa ser texto não vazio');
    }
  }
  if (mudancas.preco !== undefined) {
    if (typeof mudancas.preco !== 'number' || mudancas.preco <= 0) {
      throw new Error('preco precisa ser um número maior que 0');
    }
  }
  if (mudancas.quantidade !== undefined) {
    if (typeof mudancas.quantidade !== 'number' || mudancas.quantidade < 0) {
      throw new Error('quantidade não pode ser negativa');
    }
  }
  Object.assign(produto, mudancas);
  return produto;
}

export function removerProduto(estoque, id) {
  validarEstoque(estoque);
  const indice = estoque.produtos.findIndex((p) => p.id === id);
  if (indice === -1) return false;
  estoque.produtos.splice(indice, 1);
  return true;
}

