import { criarEstoque } from './estoque.mjs';

export function serializar(estoque) {
  if (!estoque || !Array.isArray(estoque.produtos)) {
    throw new Error('estoque inválido');
  }
  return JSON.stringify(estoque);
}

export function carregar(texto) {
  if (typeof texto !== 'string') {
    throw new Error('texto precisa ser uma string');
  }
  const dados = JSON.parse(texto);
  if (!dados || !Array.isArray(dados.produtos) || typeof dados.proximoId !== 'number') {
    throw new Error('formato de estoque inválido');
  }
  const estoque = criarEstoque();
  estoque.produtos = dados.produtos;
  estoque.proximoId = dados.proximoId;
  return estoque;
}

