import { carregar } from './persistencia.mjs';

export function valorTotalDoEstoque(estoque) {
  if (!estoque || !Array.isArray(estoque.produtos)) {
    throw new Error('estoque inválido');
  }
  return estoque.produtos.reduce((total, produto) => total + produto.preco * produto.quantidade, 0);
}

export function produtosAbaixoDoMinimo(estoque, minimo) {
  if (!estoque || !Array.isArray(estoque.produtos)) {
    throw new Error('estoque inválido');
  }
  return estoque.produtos.filter((produto) => produto.quantidade < minimo);
}

export function maisCaroDoBackup(texto) {
  const estoque = carregar(texto);
  let maisCaro;
  for (const produto of estoque.produtos) {
    if (maisCaro === undefined || produto.preco > maisCaro.preco) {
      maisCaro = produto;
    }
  }
  return maisCaro;
}

