import { test } from 'node:test';
import assert from 'node:assert/strict';
import { criarEstoque, adicionarProduto, buscarProduto, atualizarProduto, removerProduto } from './lib/estoque.mjs';
import { serializar, carregar } from './lib/persistencia.mjs';
import { valorTotalDoEstoque, produtosAbaixoDoMinimo, maisCaroDoBackup } from './lib/relatorio.mjs';

test('adicionarProduto valida, adiciona com id automático e devolve o produto', () => {
  const estoque = criarEstoque();
  const caderno = adicionarProduto(estoque, { nome: 'Caderno 96 folhas', preco: 12, quantidade: 40 });
  assert.equal(caderno.id, 1);
  assert.equal(adicionarProduto(estoque, { nome: 'Caneta azul', preco: 2, quantidade: 100 }).id, 2);
  assert.equal(estoque.produtos.length, 2);
  assert.throws(() => adicionarProduto(estoque, { nome: '', preco: 5, quantidade: 1 }));
  assert.throws(() => adicionarProduto(estoque, { nome: 'Borracha', preco: -1, quantidade: 1 }));
  assert.throws(() => adicionarProduto(estoque, { nome: 'Borracha', preco: 1, quantidade: -3 }));
});

test('buscarProduto acha pelo id e devolve undefined quando não existe', () => {
  const estoque = criarEstoque();
  adicionarProduto(estoque, { nome: 'Caderno', preco: 12, quantidade: 40 });
  assert.equal(buscarProduto(estoque, 1).nome, 'Caderno');
  assert.equal(buscarProduto(estoque, 99), undefined);
});

test('atualizarProduto muda só os campos enviados e removerProduto não quebra o próximo id', () => {
  const estoque = criarEstoque();
  adicionarProduto(estoque, { nome: 'Caderno', preco: 12, quantidade: 40 });
  adicionarProduto(estoque, { nome: 'Caneta', preco: 2, quantidade: 100 });
  const atualizado = atualizarProduto(estoque, 1, { preco: 15, quantidade: 30 });
  assert.equal(atualizado.nome, 'Caderno');
  assert.equal(atualizado.preco, 15);
  assert.equal(atualizado.quantidade, 30);
  assert.equal(atualizarProduto(estoque, 99, { preco: 1 }), undefined);
  assert.throws(() => atualizarProduto(estoque, 1, { preco: -5 }));
  assert.equal(removerProduto(estoque, 2), true);
  assert.equal(buscarProduto(estoque, 2), undefined);
  assert.equal(removerProduto(estoque, 2), false);
  assert.equal(adicionarProduto(estoque, { nome: 'Lápis', preco: 1, quantidade: 50 }).id, 3);
});

test('serializar e carregar guardam e reconstroem o estoque (persistência simulada)', () => {
  const estoque = criarEstoque();
  adicionarProduto(estoque, { nome: 'Caderno', preco: 12, quantidade: 40 });
  adicionarProduto(estoque, { nome: 'Caneta', preco: 2, quantidade: 100 });
  const texto = serializar(estoque);
  assert.equal(typeof texto, 'string');
  const deVolta = carregar(texto);
  assert.deepEqual(deVolta, estoque);
  assert.deepEqual(carregar(serializar(criarEstoque())), criarEstoque());
  assert.throws(() => carregar('isto não é json'));
  assert.throws(() => carregar('{"produtos": "errado"}'));
});

test('valorTotalDoEstoque soma preço vezes quantidade e produtosAbaixoDoMinimo filtra', () => {
  const estoque = criarEstoque();
  adicionarProduto(estoque, { nome: 'Caderno', preco: 12, quantidade: 40 });
  adicionarProduto(estoque, { nome: 'Caneta', preco: 2, quantidade: 100 });
  adicionarProduto(estoque, { nome: 'Borracha', preco: 1, quantidade: 5 });
  assert.equal(valorTotalDoEstoque(estoque), 685);
  assert.equal(valorTotalDoEstoque(criarEstoque()), 0);
  const baixos = produtosAbaixoDoMinimo(estoque, 50);
  assert.deepEqual(baixos.map((p) => p.nome), ['Caderno', 'Borracha']);
  assert.notEqual(baixos, estoque.produtos);
});

test('maisCaroDoBackup carrega o backup e devolve o produto mais caro (usa os três arquivos)', () => {
  const estoque = criarEstoque();
  adicionarProduto(estoque, { nome: 'Caderno', preco: 12, quantidade: 40 });
  adicionarProduto(estoque, { nome: 'Mochila', preco: 89, quantidade: 10 });
  assert.equal(maisCaroDoBackup(serializar(estoque)).nome, 'Mochila');
  assert.equal(maisCaroDoBackup(serializar(criarEstoque())), undefined);
});
